m[3300126]["Text121"] = tSepComeBackPack_Text[nItemId]["Text121"]		tItem[3300126]["Text131"] = tSepComeBackPack_Text[nItemId]["Text131"]		tItem[3300126]["Text141"] = tSepComeBackPack_Text[nItemId]["Text141"]		tItem[3300126]["Text151"] = tSepComeBackPack_Text[nItemId]["Text151"]		tItem[3300126]["Text161"] = tSepComeBackPack_Text[nItemId]["Text161"]	elseif nData >= tSepComeBackPack_Stc[3] then		tItem[3300126]["Text111"] = tSepComeBackPack_Text[nItemId]["Text113"]		tItem[3300126]["Text121"] = tSepComeBackPack_Text[nItemId]["Text123"]		tItem[3300126]["Text131"] = tSepComeBackPack_Text[nItemId]["Text133"]	elseif nData > tSepComeBackPack_Stc[1] and nData < tSepComeBackPack_Stc[3] then		sText = string.format(tSepComeBackPack_Text[nItemId]["Text112"], nData / 10000 + 1)		tItem[3300126]["Text111"] = sText		tItem[3300126]["Text121"] = tSepComeBackPack_Text[nItemId]["Text122"]		tItem[3300126]["Text131"] = tSepComeBackPack_Text[nItemId]["Text132"]		tItem[3300126]["Text141"] = tSepComeBackPack_Text[nItemId]["Text142"]	end		tItem[3300126]["OptionFunc1"] = string.format("SepComeBackPack_Open</N>%d",nItemId)	LinkItemGossipFunc_New(nItemId,"1-1")endfunction SepComeBackPack_Open(nItemId)	local nUserId = Get_UserId()	local nEvent = tSepComeBackPack_Reward[nItemId][1]["EventType"]	local nType = tSepComeBackPack_Reward[nItemId][1]["DataType"]	local nData = Get_UserStatisticValue(nEvent,nType,nUserId)		if nData == tSepComeBackPack_Stc[1] then		if  not Item_ChkItem(nItemId) then		return		end		RewardTemplate_UseItem(tSepComeBackPack_Reward[nItemId][1])	elseif nData == tSepComeBackPack_Stc[3] then		if  not Item_ChkItem(nItemId) then		return		end		RewardTemplate_UseItem(tSepComeBackPack_Reward[nItemId][3])	elseif nData > tSepComeBackPack_Stc[1] and nData < tSepComeBackPack_Stc[3] then		if  not Item_ChkItem(nItemId) then		return		end		RewardTemplate_UseItem(tSepComeBackPack_Reward[nItemId][2])	endendfunction SepComeBackPack_UseEquipmentPack(nItemId,nType)	if  not Item_ChkItem(nItemId) then		return	end	RewardTemplate_UseItem(tSepComeBackPack_Reward[nItemId][nType])end--------------------------------------礼包配置--------------------------------------------- 总礼包tItem[3300126] = tItem[3300126] or {}tItem[3300127] = tItem[3300126] or {}tItem[3300128] = tItem[3300126] or {}tItem[3300129] = tItem[3300126] or {}tItem[3300238] = tItem[3300126] or {}tItem[3300126]["Function"] = function(nItemId)	SepComeBackPack_Chk(nItemId)endtItem[3300126]["DialogueText"] = tSepComeBackPack_Text[3300126]tItem[3300126]["Text1-1"] = {111,121,131,141,151,161}tItem[3300126]["tOption1-1"] = {1,2}-- 天石（赠）礼包tItem[3300131] = tItem[3300131] or {}tItem[3300132] = tItem[3300131] or {}tItem[3300133] = tItem[3300131] or {}tItem[3300134] = tItem[3300131] or {}tItem[3300135] = tItem[3300131] or {}tItem[3300131]["Function"] = function(nItemId)	if not RewardTemplate_EMoneyMonoLimit(tSepComeBackPack_RewardRandom[nItemId][1][3]["RewardEMoneyMono"]) then		User_TalkChannel2005(tRewardTemplate_Text["EMoneyMono"])		return	end	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		RewardTemplate_Random(tSepComeBackPack_RewardRandom[nItemId],1)	endend-- 装备礼包tItem[3300139] = tItem[3300139] or {}tItem[3300139]["DialogueText"] = tSepComeBackPack_Text[3300139]tItem[3300139]["Text1-1"] = {111}tItem[3300139]["tOption1-1"] = {1,2,3,4}tItem[3300139]["OptionPoint1"] = "2-1"tItem[3300139]["OptionPoint2"] = "3-1"tItem[3300139]["OptionPoint3"] = "4-1"tItem[3300139]["Text2-1"] = {211}tItem[3300139]["tOption2-1"] = {5,6}tItem[3300139]["OptionFunc5"] = "SepComeBackPack_UseEquipmentPack</N>3300139</N>1"tItem[3300139]["OptionPoint6"] = "1-1"tItem[3300139]["Text3-1"] = {311}tItem[3300139]["tOption3-1"] = {7,6}tItem[3300139]["OptionFunc7"] = "SepComeBackPack_UseEquipmentPack</N>3300139</N>2"tItem[3300139]["Text4-1"] = {411}tItem[3300139]["tOption4-1"] = {8,6}tItem[3300139]["OptionFunc8"] = "SepComeBackPack_UseEquipmentPack